// Cloudflare Worker: pass traffic through; if the tunnel/origin is down (52x/530), serve the hadeda page.
const PAGE = "<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Eish.</title>\n<style>\n  html,body{margin:0;min-height:100%;background:#fcf5ea;color:#3a332b}\n  body{min-height:100vh;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:16px;box-sizing:border-box;font-family:system-ui,sans-serif;text-align:center}\n  img{width:100%;height:auto;display:block}\n  .full{max-width:1100px}\n  .stack{display:none;width:100%;max-width:480px}\n  .stack .text{width:85%;margin:0 auto 8px}\n  p{margin:12px 0 0;font-size:.95rem;opacity:.7;max-width:40em}\n  @media (orientation: portrait){.full{display:none}.stack{display:block}}\n</style></head><body>\n<img class=\"full\" src=\"data:image/webp;base64,\" width=\"1536\" height=\"1024\" alt=\"EISH. A flock of hadedas has taken down the server. We're as confused as you are.\">\n<div class=\"stack\">\n<img class=\"text\" src=\"data:image/webp;base64,\" width=\"576\" height=\"602\" alt=\"EISH. A flock of hadedas has taken down the server. We're as confused as you are.\">\n<img src=\"data:image/webp;base64,\" width=\"1110\" height=\"1024\" alt=\"\">\n</div>\n<p>Back as soon as possible. Please annoy the admin relentlessly until he fixes it, and don't feed the hadedas.</p>\n</body></html>";

export default {
  async fetch(request) {
    try {
      const res = await fetch(request);
      if (res.status < 520) return res;
    } catch (_) {}
    return new Response(PAGE, {
      status: 503,
      headers: { "content-type": "text/html; charset=utf-8", "retry-after": "86400", "cache-control": "no-store" },
    });
  },
};
